using namespace tnt::move;
using namespace tnt::move::worker;
namespace {
uint64_t NowMs(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();}
void Deadline(int){const char msg[]="{\"schema_version\":1,\"disposition\":\"uncertain\",\"reason\":\"process_deadline\"}\n";write(STDOUT_FILENO,msg,sizeof(msg)-1);_Exit(124);}
std::string Q(const std::string& s){return tnt::JsonString(s);}
Endpoint Ep(const Node& n){return {"::1",static_cast<uint16_t>(n.port)};}
std::string Base(const Input& x,const Fixture& f,const std::string& binding){std::string s="{\"schema_version\":1,\"operation_id\":"+Q(x.operation)+",\"profile_id\":\"openthread-posix-lab-v1\",\"binding_commitment\":"+Q(binding)+",\"source_commitment\":"+Q(DatasetCommitment(x.source_dataset))+",\"target_commitment\":"+Q(DatasetCommitment(x.target_dataset))+",\"source_bindings\":[";for(size_t i=0;i<f.sources.size();++i){if(i)s+=",";s+=Q(Sha256(f.id+f.sources[i].id+std::to_string(f.sources[i].pid)+std::to_string(f.sources[i].birth)));}s+= "],\"target_binding\":"+Q(Sha256(f.id+f.target.id+std::to_string(f.target.pid)+std::to_string(f.target.birth)))+",\"checked_at_ms\":"+std::to_string(NowMs())+",\"profile_verified\":true,\"runtime_verified\":true,\"independent_deadline\":true";return s;}
struct ReceiptFence: Fence{bool Arm(const std::string&)override{return true;}};
bool Matches(const Bytes& raw,const Bytes& expected){try{return DatasetCommitment(raw)==DatasetCommitment(expected);}catch(...){return false;}}
std::string Observation(Transport& transport,const Node& node,const Bytes& expected,const Bytes& pskc,const std::string& binding,bool connectivity){auto result=transport.Read(Ep(node),pskc);bool match=result.ok&&Matches(result.active,expected);std::string hash;if(result.ok){try{hash=DatasetCommitment(result.active);}catch(...){}}std::string s="{\"binding\":"+Q(binding)+",\"dataset_commitment\":"+Q(hash)+",\"checked_at_ms\":"+std::to_string(NowMs())+",\"authenticated\":"+(result.ok?"true":"false")+",\"pending_empty\":"+(result.pending.empty()?"true":"false")+",\"connectivity_verified\":"+(connectivity?"true":"false")+",\"full_match\":"+(match?"true":"false")+"}";Wipe(result.active);for(auto& [_,v]:result.pending)Wipe(v);return s;}
}
int main(int argc,char**){bool may_have_dispatched=false;std::string operation;try{if(argc!=1)throw std::runtime_error("invalid_request");std::signal(SIGALRM,Deadline);std::signal(SIGTERM,Deadline);alarm(1000);Lease lease;auto x=ReadInput();operation=x.operation;auto f=ReadFixture(x);VerifyFixture(f);auto binding=Binding(x,f);if(x.expected!="-"&&x.expected!=binding)throw std::runtime_error("binding_mismatch");auto base=Base(x,f,binding);auto transport=CreateCommissionerTransport(x.mode=="dispatch"&&f.discard_set_result,false);if(x.mode=="observe"){
 if(!ReadReceipt(x.lifecycle_directory,x.operation,RecoveryBinding(x,f),x.fenced_at_ms))throw std::runtime_error("receipt_unavailable");Fields source,target;std::string why;if(!DecodeDataset(x.source_dataset,source,why)||!DecodeDataset(x.target_dataset,target,why))throw std::runtime_error("invalid_dataset");std::string output=base+",\"worker_terminated\":true,\"recovery_binding_verified\":true,\"sources\":[";bool original_unchanged=false, all_converged=true;for(size_t i=0;i<f.sources.size();++i){if(i)output+=",";auto id=Sha256(f.id+f.sources[i].id+std::to_string(f.sources[i].pid)+std::to_string(f.sources[i].birth));auto read=transport->Read(Ep(f.sources[i]),target.at(4));bool target_match=read.ok&&read.pending.empty()&&Matches(read.active,x.target_dataset),authenticated=read.ok,pending_empty=read.ok&&read.pending.empty();std::string observed_hash;if(read.ok){try{observed_hash=DatasetCommitment(read.active);}catch(...){}}Wipe(read.active);for(auto& [_,v]:read.pending)Wipe(v);if(!target_match){transport->ResetReadSessions();auto old=transport->Read(Ep(f.sources[i]),source.at(4));if(old.ok&&old.pending.empty()&&Matches(old.active,x.source_dataset))original_unchanged=true;if(old.ok){authenticated=true;pending_empty=old.pending.empty();try{observed_hash=DatasetCommitment(old.active);}catch(...){}}Wipe(old.active);for(auto& [_,v]:old.pending)Wipe(v);}all_converged=all_converged&&target_match;output+="{\"binding\":"+Q(id)+",\"dataset_commitment\":"+Q(observed_hash)+",\"checked_at_ms\":"+std::to_string(NowMs())+",\"authenticated\":"+(authenticated?"true":"false")+",\"pending_empty\":"+(pending_empty?"true":"false")+",\"connectivity_verified\":"+(f.connectivity_verified?"true":"false")+",\"full_match\":"+(target_match?"true":"false")+"}";}auto target_result=transport->Read(Ep(f.target),target.at(4));bool target_match=target_result.ok&&target_result.pending.empty()&&Matches(target_result.active,x.target_dataset);Wipe(target_result.active);for(auto& [_,v]:target_result.pending)Wipe(v);output+= "],\"target\":"+Observation(*transport,f.target,x.target_dataset,target.at(4),Sha256(f.id+f.target.id+std::to_string(f.target.pid)+std::to_string(f.target.birth)),f.connectivity_verified);output+=",\"converged\":"+std::string(all_converged&&target_match&&!original_unchanged?"true":"false")+",\"original_source_unchanged_rejected\":"+(original_unchanged?"true":"false")+"}";std::cout<<output<<std::endl;return 0;
 }
 Request request;request.operation_id=x.operation;request.source_dataset=x.source_dataset;request.target_dataset=x.target_dataset;request.delay_ms=x.delay;request.controlled_empty=true;request.manual_recovery=true;for(auto& node:f.sources)request.sources.push_back(Ep(node));request.target=Ep(f.target);Operation move(*transport);std::string reason;if(!move.Prepare(std::move(request),reason)){std::cout<<"{\"schema_version\":1,\"operation_id\":"+Q(x.operation)+",\"disposition\":\"proven_not_sent\",\"reason\":"+Q(reason)+",\"petitions\":0,\"pending_set_invocations\":0}"<<std::endl;return 1;}if(x.mode=="inspect"){std::cout<<base+",\"ready\":true,\"disposition\":\"proven_not_sent\",\"reason\":\"ready\",\"petitions\":0,\"pending_set_invocations\":0}"<<std::endl;return 0;}
 if(x.fenced_at_ms==0||x.fenced_at_ms>NowMs()||NowMs()-x.fenced_at_ms>30000)throw std::runtime_error("fence_time_invalid");VerifyFixture(f);auto recovery=RecoveryBinding(x,f);WriteReceipt(x.lifecycle_directory,x.operation,recovery,x.fenced_at_ms,"started");ReceiptFence fence;may_have_dispatched=true;auto result=move.Confirm(fence);try{WriteReceipt(x.lifecycle_directory,x.operation,recovery,x.fenced_at_ms,DispositionName(result.disposition));}catch(...){result.disposition=Disposition::uncertain;result.reason="receipt_write_failed";}std::cout<<base+",\"disposition\":"+Q(DispositionName(result.disposition))+",\"reason\":"+Q(result.reason)+",\"petitions\":"+std::to_string(result.petitions)+",\"pending_set_invocations\":"+std::to_string(result.pending_set_invocations)+"}"<<std::endl;return result.disposition==Disposition::accepted?0:2;
 }catch(const std::exception& e){std::cout<<"{\"schema_version\":1,\"operation_id\":"<<Q(operation)<<",\"disposition\":"<<Q(may_have_dispatched?"uncertain":"proven_not_sent")<<",\"reason\":"<<Q(e.what())<<"}"<<std::endl;return 1;}}
